}
function dispose$Grid(g) {
	try {g.remove_commandEvent(on$GridServicesPurchaseInvoice$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridServicesPurchaseInvoice$ResponseComplete);} catch (ex) {}
	&ddScriptGridDispose;
}
